/**
 * Actions Language Service integration for workflow YAML editor
 * This module uses @actions/languageservice for intellisense and validation
 * instead of the custom workflow-rules.ts implementation.
 *
 * Gated behind the 'actions_workflow_language_service' feature flag.
 */

import type {CompletionContext, CompletionResult, Completion} from '@codemirror/autocomplete'
import type {EditorView} from '@codemirror/view'
import type {Text} from '@codemirror/state'
import type {Diagnostic} from '@codemirror/lint'
import {complete, hover, validate} from '@actions/languageservice'
import {clearCacheEntry} from '@actions/languageservice/utils/workflow-cache'
import {md2html} from '@github-ui/md2html'
import {TextDocument} from 'vscode-languageserver-textdocument'
import type {CompletionItem, Diagnostic as LSPDiagnostic, Hover} from 'vscode-languageserver-types'
import {CompletionItemKind} from 'vscode-languageserver-types'

const DOCUMENT_URI = 'workflow.yaml'

/**
 * Create a text document for the language service, clearing any cached parse results first.
 * The language service caches parsed workflows by URI, so we must clear the cache
 * to ensure fresh parsing when the document content changes.
 */
function createTextDocument(content: string): ReturnType<typeof TextDocument.create> {
  clearCacheEntry(DOCUMENT_URI)
  return TextDocument.create(DOCUMENT_URI, 'yaml', 1, content)
}

/**
 * Autocomplete implementation using @actions/languageservice
 */
export async function workflowAutocompleteContextWithLanguageService(
  context: CompletionContext,
): Promise<CompletionResult | null> {
  try {
    const textDocument = createTextDocument(context.state.doc.toString())

    // Convert CodeMirror position to LSP position (line/character)
    const line = context.state.doc.lineAt(context.pos)
    const lspPosition = {
      line: line.number - 1, // LSP is 0-indexed
      character: context.pos - line.from,
    }

    const suggestions = await complete(textDocument, lspPosition)

    return convertLanguageServiceCompletions(suggestions, context.state.doc, context.pos)
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Autocomplete error:', error)
    return null
  }
}

/**
 * Validation implementation using @actions/languageservice
 */
export async function workflowYamlLintSourceWithLanguageService(view: EditorView): Promise<readonly Diagnostic[]> {
  try {
    const textDocument = createTextDocument(view.state.doc.toString())

    const diagnostics = await validate(textDocument)
    return convertLanguageServiceDiagnostics(diagnostics, view)
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Validation error:', error)
    return []
  }
}

/**
 * Hover implementation using @actions/languageservice
 * Returns hover information (e.g., cron expression descriptions, context documentation)
 */
export async function workflowHoverWithLanguageService(
  view: EditorView,
  pos: number,
): Promise<{pos: number; end: number; dom: HTMLElement} | null> {
  try {
    const textDocument = createTextDocument(view.state.doc.toString())

    // Convert CodeMirror position to LSP position (line/character)
    const line = view.state.doc.lineAt(pos)
    const lspPosition = {
      line: line.number - 1, // LSP is 0-indexed
      character: pos - line.from,
    }

    const hoverResult = await hover(textDocument, lspPosition)

    if (!hoverResult || !hoverResult.contents) {
      return null
    }

    // Calculate the hover range for better tooltip stability
    let startPos = pos
    let endPos = pos
    if (hoverResult.range) {
      const startLine = view.state.doc.line(hoverResult.range.start.line + 1)
      const endLine = view.state.doc.line(hoverResult.range.end.line + 1)
      startPos = startLine.from + hoverResult.range.start.character
      endPos = endLine.from + hoverResult.range.end.character
    }

    return {pos: startPos, end: endPos, dom: createHoverTooltip(hoverResult)}
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error('[Language Service] Hover error:', error)
    return null
  }
}

/**
 * Create a styled tooltip element for hover information
 */
function createHoverTooltip(hoverResult: Hover): HTMLElement {
  const tooltip = document.createElement('div')
  tooltip.setAttribute('role', 'tooltip')
  tooltip.classList.add('Box', 'Box--condensed', 'text-small', 'color-shadow-large')

  const row = document.createElement('div')
  row.classList.add('Box-row', 'markdown-body', 'f6')

  // Handle different MarkupContent formats
  const contents = hoverResult.contents
  let markdownContent: string
  if (typeof contents === 'string') {
    markdownContent = contents
  } else if ('value' in contents) {
    // MarkupContent with kind and value
    markdownContent = contents.value
  } else if (Array.isArray(contents)) {
    markdownContent = contents.map(c => (typeof c === 'string' ? c : c.value)).join('\n')
  } else {
    markdownContent = ''
  }

  // Parse markdown and sanitize HTML
  row.innerHTML = md2html(markdownContent)

  tooltip.appendChild(row)

  return tooltip
}

/**
 * Convert language service CompletionItems to CodeMirror CompletionResult
 */
function convertLanguageServiceCompletions(items: CompletionItem[], doc: Text, cursorPos: number): CompletionResult {
  // Calculate a default 'from' position based on word start for filtering
  const cursorLine = doc.lineAt(cursorPos)
  const cursorLineNumber = cursorLine.number - 1 // Convert to 0-indexed for LSP comparison
  const charPos = cursorPos - cursorLine.from
  let wordStart = charPos
  const lineText = cursorLine.text
  while (wordStart > 0 && /[a-zA-Z0-9_-]/.test(lineText[wordStart - 1]!)) {
    wordStart--
  }
  const defaultFrom = cursorLine.from + wordStart

  // Filter out completions that don't make sense for the current cursor position
  // For example, if cursor is at `discussion: |`, don't suggest `types` as a value
  // because `types` is meant to be a nested key on a new line
  const filteredItems = items.filter(item => {
    if (item.textEdit && 'range' in item.textEdit) {
      const range = item.textEdit.range

      // If the textEdit is on a different line than the cursor, skip it
      // This happens when the language service suggests a nested key for a position
      // that should be on a new line, but the autocomplete re-triggered on the same line
      if (range.start.line !== cursorLineNumber) {
        return false
      }
    }
    return true
  })

  return {
    from: defaultFrom,
    // Allow the results to be filtered as the user types, rather than re-querying
    // the language service on each keystroke. This keeps the popup open while typing.
    validFor: /^[\w-]*$/,
    options: filteredItems.map(item => {
      // Language service puts descriptions in 'documentation', not 'detail'
      const description = typeof item.documentation === 'string' ? item.documentation : item.documentation?.value

      // If the item has a textEdit with a range, we need a custom apply function
      // to properly replace the correct range of text
      if (item.textEdit && 'range' in item.textEdit) {
        const textEdit = item.textEdit
        const startLine = doc.line(textEdit.range.start.line + 1) // Convert 0-indexed to 1-indexed
        const from = startLine.from + textEdit.range.start.character
        const newText = textEdit.newText

        const completion: Completion = {
          label: item.label,
          type: item.kind ? completionKindToType(item.kind) : undefined,
          info: description ? () => createCompletionInfoTooltip(description) : undefined,
          apply: (view, _completion, _from, currentTo) => {
            // Use the TextEdit's start position but the current cursor position (currentTo)
            // This ensures any text typed while filtering is replaced
            view.dispatch({
              changes: {from, to: currentTo, insert: newText},
              // Place cursor at end of inserted text
              selection: {anchor: from + newText.length},
            })
          },
        }
        return completion
      }

      // Fall back to simple string insertion for items without TextEdit
      return {
        label: item.label,
        type: item.kind ? completionKindToType(item.kind) : undefined,
        info: description ? () => createCompletionInfoTooltip(description) : undefined,
        apply: item.insertText || item.label,
      }
    }),
  }
}

/**
 * Create a styled tooltip element for completion info/documentation
 */
function createCompletionInfoTooltip(description: string): HTMLElement {
  const tooltip = document.createElement('div')
  tooltip.setAttribute('role', 'tooltip')
  tooltip.classList.add('Box', 'Box--condensed', 'text-small', 'color-shadow-large')

  const row = document.createElement('div')
  row.classList.add('Box-row', 'markdown-body', 'f6')

  const paragraph = document.createElement('p')
  paragraph.classList.add('mb-0')
  paragraph.textContent = description

  row.appendChild(paragraph)
  tooltip.appendChild(row)

  return tooltip
}

/**
 * Convert LSP CompletionItemKind to CodeMirror completion type
 */
function completionKindToType(kind: CompletionItemKind): string | undefined {
  switch (kind) {
    case CompletionItemKind.Function:
      return 'function'
    case CompletionItemKind.Constructor:
    case CompletionItemKind.Field:
    case CompletionItemKind.Property:
      return 'property'
    case CompletionItemKind.Variable:
      return 'variable'
    case CompletionItemKind.Class:
    case CompletionItemKind.Interface:
      return 'type'
    case CompletionItemKind.Module:
      return 'namespace'
    case CompletionItemKind.Keyword:
      return 'keyword'
    case CompletionItemKind.Text:
    case CompletionItemKind.Color:
    case CompletionItemKind.File:
      return 'text'
    default:
      return undefined
  }
}

/**
 * Create a styled tooltip element for a diagnostic message
 */
function createDiagnosticTooltip(diag: LSPDiagnostic): HTMLElement {
  const tooltip = document.createElement('div')
  tooltip.setAttribute('role', 'tooltip')
  tooltip.classList.add('Box', 'Box--condensed', 'text-small', 'color-shadow-large')

  const row = document.createElement('div')
  row.classList.add('Box-row', 'markdown-body', 'f6')

  const paragraph = document.createElement('p')
  paragraph.classList.add('mb-0')
  paragraph.textContent = diag.message

  row.appendChild(paragraph)

  // Add a link if codeDescription.href is provided
  if (diag.codeDescription?.href) {
    const linkParagraph = document.createElement('p')
    linkParagraph.classList.add('mb-0', 'mt-2')

    if (diag.code) {
      // eslint-disable-next-line i18n-text/no-en
      const textNode = document.createTextNode('Learn more: ')
      linkParagraph.appendChild(textNode)

      const link = document.createElement('a')
      link.href = diag.codeDescription.href
      link.target = '_blank'
      link.rel = 'noopener noreferrer'
      link.textContent = String(diag.code)
      link.classList.add('Link')
      // Accessibility: indicate link opens in new tab for screen readers
      const srText = document.createElement('span')
      srText.classList.add('sr-only')
      srText.textContent = ' (opens in new tab)'
      link.appendChild(srText)
      linkParagraph.appendChild(link)
    } else {
      const link = document.createElement('a')
      link.href = diag.codeDescription.href
      link.target = '_blank'
      link.rel = 'noopener noreferrer'
      // eslint-disable-next-line i18n-text/no-en
      link.textContent = 'Learn more'
      link.classList.add('Link')
      // Accessibility: indicate link opens in new tab for screen readers
      const srText = document.createElement('span')
      srText.classList.add('sr-only')
      srText.textContent = ' (opens in new tab)'
      link.appendChild(srText)
      linkParagraph.appendChild(link)
    }

    row.appendChild(linkParagraph)
  }

  tooltip.appendChild(row)

  return tooltip
}

/**
 * Convert language service Diagnostics to CodeMirror Diagnostics
 */
function convertLanguageServiceDiagnostics(lspDiagnostics: LSPDiagnostic[], view: EditorView): Diagnostic[] {
  return lspDiagnostics.map(diag => ({
    from: view.state.doc.line(diag.range.start.line + 1).from + diag.range.start.character,
    to: view.state.doc.line(diag.range.end.line + 1).from + diag.range.end.character,
    // LSP severity: 1=Error, 2=Warning, 3=Info, 4=Hint. Default to error if not specified.
    severity: diag.severity === 2 ? 'warning' : diag.severity === 3 || diag.severity === 4 ? 'info' : 'error',
    message: '', // handled by renderMessage
    renderMessage: () => createDiagnosticTooltip(diag),
  }))
}
